relativeInstruction(): { key: string; deg: number } | null {
  if (!this.headingActive || this.headingDeg == null || this.azimuthDeg == null) {
    return null;
  }
  const diff = this.circularDiffDeg(this.azimuthDeg, this.headingDeg);
  const mag = Math.abs(diff);
  if (mag <= FACING_THRESHOLD_DEG) {
    // Azimut OK — le message « face à la cible » n'apparaît que si l'inclinaison l'est aussi.
    if (this.isPitchAligned()) {
      return { key: 'ASTRO_COMPASS.FACING', deg: 0 };
    }
    return { key: 'ASTRO_COMPASS.TURN_OK', deg: 0 };
  }
  return {
    key: diff > 0 ? 'ASTRO_COMPASS.TURN_RIGHT' : 'ASTRO_COMPASS.TURN_LEFT',
    deg: Math.round(mag)
  };
}

/**
 * Consigne d'inclinaison (toujours active dès que le pitch téléphone est connu) :
 * indépendante de l'auto-détection et du calage azimut.
 */
tiltInstruction(): { key: string; deg: number } | null {
  if (
    this.devicePitchDeg == null ||
    this.elevationDeg == null ||
    this.elevationDeg < -1
  ) {
    return null;
  }
  const diff = this.elevationDeg - this.devicePitchDeg;
  const mag = Math.abs(diff);
  if (mag <= PITCH_THRESHOLD_DEG) {
    return { key: 'ASTRO_COMPASS.TILT_OK', deg: 0 };
  }
  return {
    key: diff > 0 ? 'ASTRO_COMPASS.TILT_UP' : 'ASTRO_COMPASS.TILT_DOWN',
    deg: Math.round(mag)
  };
}

elevationGaugePercent(): number {
  const el = this.elevationDeg;
  if (el == null) {
    return 0;
  }
  const clamped = Math.max(0, Math.min(90, el));
  return (clamped / 90) * 100;
}

/** Position (0–100 %) du téléphone sur la jauge d'élévation. */
devicePitchGaugePercent(): number {
  const p = this.devicePitchDeg;
  if (p == null) {
    return 0;
  }
  const clamped = Math.max(0, Math.min(90, p));
  return (clamped / 90) * 100;
}

aboveHorizon(): boolean {
  return this.elevationDeg != null && this.elevationDeg >= -1;
}

isPitchAligned(): boolean {
  if (this.devicePitchDeg == null || this.elevationDeg == null || this.elevationDeg < -1) {
    // Sans inclinaison (desktop) : on ne bloque pas sur le pitch.
    return this.devicePitchDeg == null;
  }
  return Math.abs(this.elevationDeg - this.devicePitchDeg) <= PITCH_THRESHOLD_DEG;
}

isYawAligned(): boolean {
  if (!this.headingActive || this.headingDeg == null || this.azimuthDeg == null) {
    return false;
  }
  return Math.abs(this.circularDiffDeg(this.azimuthDeg, this.headingDeg)) < FACING_THRESHOLD_DEG;
}

isFacing(): boolean {
  if (
    !this.headingActive ||
    this.headingDeg == null ||
    this.azimuthDeg == null ||
    this.elevationDeg == null ||
    this.elevationDeg < -1
  ) {
    return false;
  }
  return this.isYawAligned() && this.isPitchAligned();
}

