  if (
    !this.headingActive ||
    this.devicePitchDeg == null ||
    this.elevationDeg == null ||
    this.elevationDeg < -1
  ) {
    return null;
  }
  // Priorité à la rotation horizontale si elle n'est pas encore bonne.
  if (this.headingDeg != null && this.azimuthDeg != null) {
    const yawMag = Math.abs(this.circularDiffDeg(this.azimuthDeg, this.headingDeg));
    if (yawMag > FACING_THRESHOLD_DEG) {
      return null;
    }
  }
