  const mag = Math.abs(diff);
  if (mag <= PITCH_THRESHOLD_DEG) {
    return null;
  }
  return {
    key: diff > 0 ? 'ASTRO_COMPASS.TILT_UP' : 'ASTRO_COMPASS.TILT_DOWN',
    deg: Math.round(mag)
  };
