}

isPitchAligned(): boolean {
  if (this.devicePitchDeg == null || this.elevationDeg == null || this.elevationDeg < -1) {
    // Sans inclinaison (desktop / calage souris) : on ne bloque pas sur le pitch.
    return this.devicePitchDeg == null;
  }
  return Math.abs(this.elevationDeg - this.devicePitchDeg) <= PITCH_THRESHOLD_DEG;
}

isFacing(): boolean {
  if (
    !this.headingActive ||
    this.headingDeg == null ||
    this.azimuthDeg == null ||
    this.elevationDeg == null ||
    this.elevationDeg < -1
  ) {
    return false;
  }
  const yawOk =
    Math.abs(this.circularDiffDeg(this.azimuthDeg, this.headingDeg)) < FACING_THRESHOLD_DEG;
  return yawOk && this.isPitchAligned();
}

